const classEscape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const classDays = ['星期一','星期二','星期三','星期四','星期五'];
window.renderClassMobile = (code, mode, day = 1) => {
 const rows=window.CLASS_TIMETABLES[code][mode];
 const host=document.getElementById('ychMobileSchedule');
 host.innerHTML=classDays.map((name,d)=>'<section class="ych-mobile-day"'+(d+1===day?'':' hidden')+'><h4>'+name+'</h4>'+rows.map(r=>'<div class="ych-mobile-lesson"><time>'+r.time+'</time><div><strong>'+classEscape(r.values[d]||r.label||'空堂')+'</strong></div></div>').join('')+'</section>').join('');
 host.hidden=false;
};
window.renderClassTimetable = (code, mode) => {
 const rows=window.CLASS_TIMETABLES[code][mode];
 if(!rows)return;
 document.querySelector('#selectedTeacherRoles').textContent=code+' 班 · 2026–2027 上課時間表';
 document.querySelector('.weekly-schedule-table').setAttribute('aria-label',code+' 班每周時間表');
 document.querySelector('#ychCurrentWeek').textContent='顯示：'+(mode==='single'?'單周':'雙周');
 document.querySelectorAll('[data-ych-week]').forEach(b=>{b.classList.toggle('active',b.dataset.ychWeek===mode);b.setAttribute('aria-pressed',String(b.dataset.ychWeek===mode));});
 const skip=new Set();
 document.querySelector('#ychScheduleBody').innerHTML=rows.map((row,r)=>'<tr'+(row.label&&r!==13?' class="schedule-break-row"':'')+'><td class="schedule-special-label">'+(row.label?'<span class="schedule-special-name">'+row.label+'</span>':'')+'<small><span class="schedule-time-range">'+row.time+'</span></small></td>'+row.values.map((value,d)=>{
  if(skip.has(r+'-'+d))return '';
  let span=1;
  if(value&&r>0&&r<13&&!row.label)while(r+span<13&&!rows[r+span].label&&rows[r+span].values[d]===value){skip.add((r+span)+'-'+d);span++;}
  return '<td rowspan="'+span+'" data-schedule-day="'+(d+1)+'"'+(span>1?' class="is-multi-period"':'')+'>'+(value?'<span class="schedule-cell-item"><strong>'+classEscape(value).replace(/\n/g,'<br>')+'</strong></span>':'')+'</td>';
 }).join('')+'</tr>').join('');
 window.renderClassMobile(code,mode);
};
